@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-nowrap" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<span class="badge @BadgeClass rounded-pill ms-2">@AlertService.CurrentLowStockCount</span>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    private string BadgeClass => AlertService.CurrentLowStockCount > 5 ? "bg-danger" : "bg-warning text-dark";

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _alertHandler;

        // Refresh alerts when warehouse changes
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

