@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @CardBorder">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @TextClass">@AlertService.CurrentLowStockCount</p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    private string CardBorder => AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-warning";
    private string TextClass => AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-warning";

    protected override void OnInitialized()
    {
        // Subscribe to alert changes from the polling service
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _alertHandler;

        // Subscribe to warehouse changes to re-render
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling — this page is the trigger for the poll loop
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        AlertService.OnAlertDataChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

